// =====================================================
// CONFIGURAÇÃO DE SENHAS — edite apenas este bloco
// =====================================================
const SENHA_NORMAL = 'TROQUE_ESTA_SENHA';       // senha comum
const SENHA_MESTRA = 'TROQUE_A_SENHA_MESTRA';       // senha mestra
const LIMITE_MESTRA_POR_DIA = 5;   // total de relatórios/dia da senha mestra
const FUSO_HORARIO = 'America/Sao_Paulo';
// Senha normal = 1 relatório por senha. Para liberar outro relatório,
// basta TROCAR o valor de SENHA_NORMAL acima (o controle reinicia sozinho).
// =====================================================

const item = $input.first().json;

// Chamada vinda do chat (tem chatInput/action) ou da tela de senha (webhook)
const ehChat = item.chatInput !== undefined || item.action !== undefined;
const senhaInformada = String(
  ehChat ? ((item.metadata && item.metadata.senha) || '') : ((item.body && item.body.senha) || '')
).trim().toUpperCase();

const sd = $getWorkflowStaticData('global');
const hoje = new Date().toLocaleDateString('en-CA', { timeZone: FUSO_HORARIO });

// Contador diário da senha mestra
if (!sd.mestra || sd.mestra.data !== hoje) {
  sd.mestra = { data: hoje, usados: 0, sessoes: [] };
}

// Controle de uso único da senha normal (guarda só uma marca, não a senha)
const gerarMarca = (s) => {
  let h = 5381;
  for (const c of s) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0;
  return String(h);
};
const marcaNormal = gerarMarca(SENHA_NORMAL.toUpperCase());
if (!sd.normal || sd.normal.marca !== marcaNormal) {
  sd.normal = { marca: marcaNormal, usada: false, sessao: null };
}

let tipo = null;
if (senhaInformada && senhaInformada === SENHA_NORMAL.toUpperCase()) tipo = 'normal';
else if (senhaInformada && senhaInformada === SENHA_MESTRA.toUpperCase()) tipo = 'mestra';

let ok = !!tipo;
let mensagem = '';
if (!tipo) {
  mensagem = ehChat
    ? 'Acesso não autorizado. Atualize a página e informe a senha.'
    : 'Senha incorreta, por favor, tente novamente';
} else if (tipo === 'mestra' && sd.mestra.usados >= LIMITE_MESTRA_POR_DIA) {
  ok = false;
  mensagem = `O limite diário de ${LIMITE_MESTRA_POR_DIA} relatórios da senha mestra foi atingido. Tente novamente amanhã.`;
} else if (tipo === 'normal' && sd.normal.usada) {
  ok = false;
  mensagem = 'Esta senha já foi utilizada para gerar um relatório. Solicite uma nova senha ao administrador.';
}

if (!ehChat) {
  return [{ json: { rota: 'auth', ok, tipo: ok ? tipo : null, mensagem } }];
}
if (!ok) {
  return [{ json: { rota: 'bloqueado', mensagem } }];
}
return [{ json: { ...item, rota: 'chat', tipo, dataHoje: hoje, marcaNormal } }];

// Registra o uso quando a mensagem final de sucesso é devolvida
const sd = $getWorkflowStaticData('global');
const resposta = $input.first().json;
const texto = String(resposta.output ?? '');
const acesso = $('Validar Acesso').first().json;

if (texto.includes('diagnóstico foi gerado com sucesso')) {
  const sid = acesso.sessionId || 'sem-sessao';

  if (acesso.tipo === 'mestra') {
    if (!sd.mestra || sd.mestra.data !== acesso.dataHoje) {
      sd.mestra = { data: acesso.dataHoje, usados: 0, sessoes: [] };
    }
    // evita contar duas vezes a mesma conversa
    if (!sd.mestra.sessoes.includes(sid)) {
      sd.mestra.sessoes.push(sid);
      sd.mestra.usados += 1;
    }
  }

  if (acesso.tipo === 'normal') {
    // só marca se a senha ainda é a mesma da conversa (não foi trocada no meio)
    if (sd.normal && sd.normal.marca === acesso.marcaNormal) {
      sd.normal.usada = true;
      sd.normal.sessao = sid;
    }
  }
}

return [{ json: { output: texto } }];
